WITH filtered AS (SELECT *, DATEDIFF(CURRENT_DATE(), launch_date) AS days_since_launch_date FROM products WHERE launch_date > DATE '2023-10-28' AND SIZE(tags) > 2), remaining_keys AS (SELECT supplier_id FROM filtered INTERSECT SELECT supplier_id FROM products WHERE launch_date < '2023-11-01'), reconciled AS (SELECT s.* FROM filtered s INNER JOIN remaining_keys k ON s.supplier_id = k.supplier_id), with_dims AS (SELECT e.*, d.country, d.rating, d.supplier_name FROM reconciled e LEFT JOIN suppliers d ON e.supplier_id = d.id), eligible AS (SELECT s.* FROM with_dims s WHERE NOT EXISTS (SELECT 1 FROM store_sales c WHERE c.product_id = s.id AND c.sale_date <= '2023-12-01')), not_flagged AS (SELECT s.* FROM eligible s WHERE NOT EXISTS (SELECT 1 FROM store_sales c WHERE c.product_id = s.id AND c.store_id IN (1, 2, 4, 5))), filtered_products AS (SELECT id, product_name, category, brand, price, cost, stock_qty, launch_date, days_since_launch_date, country, rating, supplier_name, LENGTH(supplier_name) AS supplier_name_length FROM not_flagged WHERE launch_date >= TO_DATE('2023-11-19') AND supplier_id IS NOT NULL AND price <= 1150), not_flagged_products AS (SELECT s.* FROM filtered_products s WHERE NOT EXISTS (SELECT 1 FROM order_items x WHERE x.product_id = s.id AND x.product_id IS NOT NULL)) SELECT CASE WHEN stock_qty >= 442 THEN 'LARGE' ELSE 'SMALL' END AS stock_qty_tier, BIT_AND(stock_qty) AS stock_qty_bit_and, CORR(stock_qty, price) AS corr_stock_qty_price, COUNT(DISTINCT country) AS distinct_countries FROM not_flagged_products GROUP BY CASE WHEN stock_qty >= 442 THEN 'LARGE' ELSE 'SMALL' END
